function validate([root, target]) {
  if (!Number.isInteger(target) || target < 0 || target > 1000) return 'target is a whole number from 0 to 1000.';
  if (!Array.isArray(root) || !root.length || root[0] === null) return 'The tree needs at least one node.';
  if (root.some(v => v !== null && (!Number.isInteger(v) || v < 0 || v > 1000))) return 'Node values are whole numbers from 0 to 1000.';
  const nodes = [{ val: root[0], left: null, right: null }];
  let i = 1;
  for (let q = 0; q < nodes.length && i < root.length; q++) {
    for (const side of ['left', 'right']) {
      if (i < root.length && root[i] !== null) {
        nodes[q][side] = { val: root[i], left: null, right: null };
        nodes.push(nodes[q][side]);
      }
      i++;
    }
  }
  if (root.slice(i).some(v => v !== null)) return 'The level-order list has values with no parent.';
  if (nodes.length > 50) return 'The tree has at most 50 nodes.';
  const inorder = [];
  const visit = node => { if (node) { visit(node.left); inorder.push(node.val); visit(node.right); } };
  visit(nodes[0]);
  for (let k = 1; k < inorder.length; k++) if (inorder[k - 1] >= inorder[k]) return 'root must be a binary search tree with distinct values.';
  return null;
}

