function splitBST(root, target) {
  if (root === null) {
    return [null, null];
  }
  if (root.val <= target) {
    const [small, large] = splitBST(root.right, target);
    root.right = small;
    return [root, large];
  }
  const [small, large] = splitBST(root.left, target);
  root.left = large;
  return [small, root];
}

