function splitBST(root, target) {
  // Apply the definition directly: record every node's original parent, then give each node a fresh copy whose
  // parent is the nearest original ancestor on the same side.
  const parent = new Map();
  const order = [];
  const walk = (node, up) => {
    if (!node) return;
    parent.set(node, up);
    order.push(node);
    walk(node.left, node);
    walk(node.right, node);
  };
  walk(root, null);
  const copy = new Map(order.map(node => [node, new TreeNode(node.val)]));
  const roots = [null, null];
  for (const node of order) {
    const side = node.val <= target ? 0 : 1;
    let up = parent.get(node);
    while (up && (up.val <= target ? 0 : 1) !== side) up = parent.get(up);
    if (!up) roots[side] = copy.get(node);
    else if (node.val < up.val) copy.get(up).left = copy.get(node);
    else copy.get(up).right = copy.get(node);
  }
  return roots;
}

