function generate(rand, size) {
  const n = size === 'large' ? 50 : 1 + Math.floor(rand() * 8);
  const top = size === 'large' ? 1000 : Math.min(1000, n + Math.floor(rand() * 15));
  const pool = Array.from({ length: top + 1 }, (_, v) => v);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const values = pool.slice(0, n);
  // Sometimes insert in sorted order to get a long, skewed chain.
  const shape = rand();
  if (shape < 0.15) values.sort((a, b) => a - b);
  else if (shape < 0.3) values.sort((a, b) => b - a);
  const nodes = [];
  for (const val of values) {
    const node = { val, left: null, right: null };
    if (!nodes.length) { nodes.push(node); continue; }
    let at = nodes[0];
    for (;;) {
      const side = val < at.val ? 'left' : 'right';
      if (!at[side]) { at[side] = node; break; }
      at = at[side];
    }
    nodes.push(node);
  }
  const out = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    if (!node) { out.push(null); continue; }
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  const sorted = values.slice().sort((a, b) => a - b);
  const roll = rand();
  let target;
  if (roll < 0.4) target = sorted[Math.floor(rand() * sorted.length)];
  else if (roll < 0.5) target = rand() < 0.5 ? 0 : 1000;
  else target = Math.floor(rand() * (Math.min(1000, sorted[sorted.length - 1] + 2) + 1));
  return [out, target];
}
